for i in [0]+list(range(10,20)):
 knots=[-3,-2,-1,0,1,2,3] if i==0 else list(range(1,10)) if i==12 else [2,4,6,8]
 spec += [('h',i,k) for k in knots]
for stage in range(3):
 if stage==1:
  spec += [('p',i,j) for i in range(20) for j in range(i+1,20)]
 if stage==2:
  spec += [('q',12,i,k,(-4.2 if i==0 else 0)) for i in range(20) if i!=12 for k in [3,6]]
 D=design(X,spec);Dt=design(Xt,spec);beta=fit(D,y)
 print('stage',stage,'nterms',len(spec),'train',score(y,D@beta),'valid',score(yt,Dt@beta))
 if stage==2:
  print('intercept',beta[0])
  for t,b in zip(spec,beta[1:]):print(t,round(float(b),7))

